"""Regression guard for the config.py split.

Ensures every defined name from the monolithic config.py is still importable from
app.config with the SAME value. Run: .venv/Scripts/python.exe server/scripts/config_split_selftest.py
"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

import app.config as C

# Project root for the running machine, so absolute config paths (e.g. SQLITE_DB_PATH)
# can be masked the same way the snapshot was masked at generation time. The selftest
# lives in server/scripts/, so the project root is two levels up.
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
MASK = "<PROJECT_ROOT>"
def _mask(s):
    # repr() escapes backslashes, so the project root appears in three forms:
    # single-sep (rare), forward-slash, and doubled-sep (the repr-escaped form).
    # Mask all three so no absolute path leaks into the committed snapshot.
    s = s.replace(ROOT, MASK)
    s = s.replace(ROOT.replace(os.sep, "/"), MASK)
    s = s.replace(ROOT.replace(os.sep, os.sep + os.sep), MASK)
    return s

